const config = {
  ...defaults,
  ...loadFile('config.yaml'),
  ...fromEnv(process.env),
};
validate(config);              // throws and exits on any missing/invalid field
config.paymentKey = await secretsManager.get('payment-key');
startServer(config);           // only reachable once config is known good

